import {disengage, goTo, mine, note, orient, sell, sleep, unwrap} from 'play';

// Dock at base: disengage if a fight is in the way, back off on ServerBusy, fail on anything else.
async function goHome(): Promise<void> {
  for (let attempt = 0; ; attempt++) {
    const trip = await goTo('sol_base');
    if (trip.ok) return;
    if (trip.error._tag === 'InBattle') {
      note(`battle with ${trip.error.enemy} — disengaging`);
      await disengage();
      continue;
    }
    if (trip.error._tag === 'ServerBusy' && attempt < 5) {
      await sleep(1000 * 2 ** attempt);
      continue;
    }
    throw trip.error;
  }
}

export default async function main() {
  // 1. Mine until the hold is full: HoldFull is the signal to stop, anything else fails the program.
  for (;;) {
    const m = await mine();
    if (m.ok) {
      note(`mined ${m.value.item_id} x${m.value.quantity}`);
      continue;
    }
    if (m.error._tag === 'HoldFull') {
      note(`hold full (${m.error.used}/${m.error.capacity})`);
      break;
    }
    throw m.error;
  }

  // 2. Fly home and dock.
  await goHome();

  // 3. Sell everything in the hold — every item, all of it (omitting quantity means all of it).
  const here = unwrap(await orient());
  if (here.cargo.length === 0) {
    note('hold empty, nothing to sell');
    return {total: 0, fills: [], short: []} as never; // unreachable: we mined until HoldFull
  }
  const sold = unwrap(await sell(here.cargo.map(r => ({item_id: r.item_id}))));
  note(`sold everything for ${sold.total} credits`);
  return sold;
}

