import {goTo, sell, note, unwrap, orient, salvage, disengage, sleep} from 'play';

async function arriveAt(id: string): Promise<void> {
  for (;;) {
    const trip = await goTo(id);
    if (trip.ok) return;

    if (trip.error._tag === 'InBattle') {
      await disengage();
      continue;
    }

    if (trip.error._tag === 'ServerBusy') {
      await sleep(trip.error.retryAfterMs);
      continue;
    }

    throw trip.error;
  }
}

async function sellEverything(): Promise<void> {
  for (;;) {
    const here = unwrap(await orient());
    if (here.cargo.length === 0) return;

    const sale = await sell(here.cargo.map(row => ({item_id: row.item_id})));
    if (sale.ok) return;

    if (sale.error._tag === 'InBattle') {
      await disengage();
      continue;
    }

    if (sale.error._tag === 'NotDocked') {
      await arriveAt('sol_base');
      continue;
    }

    throw sale.error;
  }
}

async function clearHold(): Promise<void> {
  await arriveAt('sol_base');
  await sellEverything();
  await arriveAt('sol_debris');
}

export default async function main() {
  for (;;) {
    const s = await salvage();

    if (s.ok) {
      continue;
    }

    if (s.error._tag === 'NoWreck') {
      note('no wreck');
      return;
    }

    if (s.error._tag === 'InBattle') {
      await disengage();
      continue;
    }

    if (s.error._tag === 'HoldFull') {
      await clearHold();
      continue;
    }

    throw s.error;
  }
}

