import {
  completeMissions,
  disengage,
  goTo,
  mine,
  note,
  orient,
  sell,
  service,
  unwrap,
} from 'play';

async function arriveAt(id: string) {
  for (;;) {
    const r = await goTo(id);
    if (r.ok) return;

    if (r.error._tag === 'InBattle') {
      await disengage();
      continue;
    }

    throw r.error;
  }
}

export default async function main() {
  try {
    await arriveAt('kepler_belt');

    for (;;) {
      const r = await mine();
      if (r.ok) continue;

      if (r.error._tag === 'HoldFull') break;

      if (r.error._tag === 'InBattle') {
        await disengage();
        continue;
      }

      throw r.error;
    }

    await arriveAt('kepler_base');

    const here = unwrap(await orient());
    const copper = here.cargo
      .filter((row) => row.item_id === 'copper_ore')
      .map((row) => ({ item_id: row.item_id }));

    if (copper.length > 0) {
      unwrap(await sell(copper));
    }

    unwrap(await service());

    const missions = await completeMissions();
    if (!missions.ok && missions.error._tag !== 'NothingCompletable') {
      throw missions.error;
    }
  } finally {
    const finalHere = unwrap(await orient());
    note(`current credits: ${finalHere.credits}`);
  }
}
